def source(id,url,title,authority,section,passage,typ='official-guidance',date=None,status='effective',notes='',verified=True,access='read'):
 s=dict(id='pr-'+id,url=url,title=title,authority=authority,type=typ,section=section,supportingPassage=passage,publicationDate=date,effectiveDate=None,fetchedAt=NOW,substantiveVerifiedAt=NOW if verified else None,nextReview='2026-12-12',legalStatus=status,reviewerStatus=REVIEW,accessStatus=access,notes=notes);sources.append(s);return s['id']
