def rule(id,title,topic,jurisdiction,activity,actor,app,requirement,trigger,deadline,evidence,sids,limits,status='conditional',exceptions='Task- and jurisdiction-specific exceptions require separate review.'):
 r=dict(id='practice-'+id,title=title,topic=topic,jurisdiction=jurisdiction,activity=activity,affectedParty=actor,applicability=app,requirement=requirement,exceptions=exceptions,trigger=trigger,deadline=deadline,fee=None,renewal='Check controlling instrument and current agency instructions.',dependencies=[],evidence=evidence,sourceIds=sids,status=status,legalStatus='effective' if topic!='commercial-feasibility' else 'recommended-practice',verifiedAt=NOW,nextReview='2026-12-12',conflicts=[],interpretationLimits=limits,dependentPaths=[],reviewerStatus=REVIEW);rules.append(r);return r['id']
