RS=rule('service-contract','Identify federal service-contract wage obligations before bidding','employment','Federal','Covered federal or DC service contracts','Contractor and subcontractor','Service Contract Act coverage, contract value, location, service-worker duties and exceptions must be assessed.','Use applicable wage determination and fringe-benefit terms when pricing and performing covered work.','Bid review / contract award','Before bid commitment and throughout covered performance',['Solicitation and clauses','Wage determination','Job mapping','Payroll/benefit cost model'],[DOL],['No wage rate quoted.','Private facilities contracts are not automatically covered by the federal SCA.'])
RE=rule('e-ownership','Separate enterprise nationality from place of incorporation','immigration','Federal','Planning E treaty investor/employee work','Proposed investor / employee and enterprise','Actual individual, ultimate ownership, control, qualifying investment and treaty conditions.','Trace ultimate ownership and intended individual duties; do not infer E-2 eligibility from subsidiary address.','Before relying on a person for U.S. work','Before work or immigration commitment',['Ownership tree','Nationality facts without uploads','Individual role','Investment allocation'],[E,TREATY],['No personal eligibility decision.','FAM consular detail and later changes need review.'])
RC=rule('court-scope','Record court-search coverage and limitations','commercial-feasibility','Federal / relevant state and local courts','Partner due diligence','Brand due-diligence lead','Entity names and associated parties selected for proportionate lawful review.','Document court systems searched, dates, aliases and case disposition; missing results are not certification.','Before a partner commitment','Evidence-date policy chosen by team',['Entity identifiers','Search scope','Case documents','Response to identified disputes'],[PACER],['PACER covers federal courts; state/local and other systems remain separate.'],'conditional','Recommended business practice; not a government certification.')

def sec(h,*ps,bullets=None,table=None,sids=None):
 d={'heading':h,'paragraphs':list(ps)}
 if bullets:d['bullets']=bullets
 if table:d['table']={'headers':table[0],'rows':table[1]}
 if sids:d['sourceIds']=sids
 return d

def guide(id,path,title,desc,family,topic,juris,sections,sids,stage,out,limits=None,rids=None,status='published',scenario=None):
 g=dict(id=id,path=path,title=title,description=desc,family=family,topic=topic,jurisdictions=juris,status=status,lastReviewed=D if status=='published' else None,reviewStatus=REVIEW if status=='published' else 'Editorial hold; source or procedural review incomplete',readMinutes=max(3,round(sum(len(' '.join(s['paragraphs']).split())+sum(len(b.split()) for b in s.get('bullets',[])) for s in sections)/180)),ruleIds=rids or [],sections=sections,sourceIds=sids,nextStage=stage,practicalOutput=out,limitations=limits or [])
 if scenario:g['scenarioType']=scenario;g['label']='Fictional scenario — all businesses and figures are illustrative' if scenario=='fictional' else 'Real case — historical documents and stated procedural limits'
 (cases if family=='case' else guides).append(g)
 for r in rules:
  if r['id'] in g['ruleIds']:r['dependentPaths'].append(path)
 return g

# A–H: original fictional scenarios, with assumption provenance visible in every title and description.
guide('case-cleaning-zero','/cases/cleaning-manager-royalty/','Fictional case: the cleaning unit with no surplus left','A fictional Singapore cleaning business discovers how a manager and royalty consume an apparent annual surplus.','case','commercial-feasibility',['Federal','Singapore'],[
 sec('The decision','Fictional scenario. A Singapore commercial-cleaning owner wants a U.S. operation run by a local general manager while the owner remains abroad. The team copies a home-market annual worksheet into USD. Revenue is $1,000,000. The worksheet shows $180,000 before a dedicated manager and the proposed brand royalty. All figures are teaching assumptions, not industry averages or actual franchise earnings.'),
 sec('The overlooked fact','The $820,000 already deducted includes frontline labour, employer payroll costs on those workers, cleaning materials, vehicle use, insurance, occupancy and ordinary administration. It expressly excludes the dedicated general manager, brand royalty, debt service, income taxes and replacement capital. The team must check its own ledger rather than add a second allowance for costs already included.'),
 sec('The consequence', 'A fully loaded manager costs $120,000 in this fictional model. A 6% royalty on $1,000,000 revenue costs $60,000. The arithmetic is $180,000 − $120,000 − $60,000 = $0 at that stage. Zero here means the listed costs consume the listed surplus; it does not mean the business has paid debt, funded growth or generated distributable cash.',table=(['Fictional annual USD input','Amount'],[['Revenue','$1,000,000'],['Costs already in original worksheet','$820,000'],['Surplus before manager and royalty','$180,000'],['Dedicated manager, fully loaded','$120,000'],['Royalty:6% of revenue','$60,000'],['Surplus at this stage','$0']])),
 sec('Separate accounting profit from cash','An invoice can be revenue before the customer pays. If payroll falls due before collection, a unit showing an accounting profit can still need working capital. SBA explains the cash/accrual distinction; our figures are an original exercise rather than a forecast. Record invoice dates, expected receipts, deposits, equipment payments and debt on the cash schedule.',sids=[FIN]),
 sec('Reusable decision checklist','Output: a dated unit model whose owner is the CFO or finance lead. Rebuild three scenarios from documented assumptions; do not merely increase every revenue line.',bullets=['Mark every cost included, excluded or unknown.','Record manager role, salary evidence, benefits and payroll assumptions.','Confirm what revenue the royalty applies to and when payment falls due.','Test a slower customer ramp and longer receivables; keep costs that do not fall with sales.','Keep tax, debt, reinvestment and support-office costs separately visible.','Decision: revise the fee/model, test different delivery economics, investigate further or pause.'])
],[FIN],3,'An annual unit model plus a separate dated cash schedule',['Fictional teaching inputs, no earnings representation for an actual franchise.','No U.S. location, wage quote or tax analysis supplied.'],scenario='fictional')

guide('case-license','/cases/licensing-label-franchise-obligations/','Fictional case: a German technical-services “license”','A fictional German service company maps payments, operational support and brand controls before anyone decides the legal classification.','case','classification',['Federal','Germany'],[
 sec('The decision','Fictional scenario. A German technical-services company offers a U.S. partner its name, operating procedures, mandatory job software, initial training and continuing field support. The partner pays an initial fee and continuing charges. The sales director wants to call the agreement a license because the partner already runs another business.'),
 sec('The overlooked fact','The federal definition in16 CFR436.1 addresses a continuing commercial relationship whatever its label. Brand association, significant operational control or assistance, and required payments are relevant facts. A separate exemption analysis and separate state analysis still follow. One software rule or one manual does not produce an automatic result.',sids=[FR]),
 sec('Examine what changes the overall business','The management team separates requirements protecting the trademark from directions about how the partner runs delivery. The FTC guide distinguishes these kinds of control. Record whether procedures are optional, who enforces them, how much of the partner business uses the system, what support was promised orally, and what the buyer reasonably relies on.',sids=[FG],table=(['Relationship fact','Evidence to collect'],[['Brand','Mark rights and permission scope'],['Payments','All fee, purchase, affiliate and timing obligations'],['Operations','Method, site, customer, quality and system requirements'],['Assistance','Training, launch, bids, field support and sales promises'],['Jurisdiction','Seller, buyer, proposed operation and offer locations']])),
 sec('The useful next document','Draw the actual relationship: German brand → U.S. partner for brand rights and support; U.S. partner → brand or affiliate for fees; U.S. partner → customer for service delivery. Add which party recruits staff, wins accounts, invoices, bears rework and monitors service. Area representatives and master operators need separate arrows, not a new label on the same chart.'),
 sec('Reusable evidence checklist','Output: a relationship factsheet owned by the expansion lead, prepared before offers are made.',bullets=['Retain draft contracts, price lists and sales scripts.','Record actual support and controls, including informal promises.','List direct and indirect payments and recipients.','Identify the first transaction, communication and operating jurisdictions.','Ask the reviewer to analyse definitions, exclusions, exemptions and state overlays separately.','Record the conclusion and factual assumptions outside this educational tool; completion provides no sales clearance.'])
],[FR,FG],1,'A relationship factsheet and money/support flow diagram',['No automated franchise classification or exemption approval.'],[RFR],scenario='fictional')

guide('case-funding','/cases/net-worth-is-not-project-funding/','Fictional case: a wealthy British partner with a $200,000 gap','A fictional facilities-services candidate has $4million net worth but insufficient demonstrated cash for the project.','case','commercial-feasibility',['United Kingdom','Federal'],[
 sec('The decision','Fictional scenario. A British facilities company considers granting U.S. rights to a candidate who reports $4million in net worth. The candidate has $200,000 of accessible, unencumbered money allocated to this project. Launch needs $250,000 and a further $150,000 liquidity reserve under the team’s illustrative plan. None of these amounts is a market benchmark.'),
 sec('The overlooked fact','Net worth is assets less liabilities, not the cash available on a launch date. Real estate equity may be valuable but unavailable without a sale or borrowing. A securities account can be pledged, jointly controlled or committed elsewhere. A loan term sheet can have unfulfilled conditions. The balance sheet and cash schedule answer different questions; the SBA finance guide explains the accounting foundation.',sids=[FIN]),
 sec('The consequence','Required project funding is $250,000 + $150,000 = $400,000. Demonstrated allocated funding is $200,000. The remaining gap is $200,000 unless other committed capital is established. This exercise treats the reserve as additional liquidity, not a second copy of launch costs already counted.',table=(['Fictional USD measure','Amount','Meaning'],[['Reported net worth','$4,000,000','Not a funding commitment'],['Accessible, allocated capital','$200,000','Evidence still needs date and restrictions'],['Launch expenditure','$250,000','Timing and scope must be itemised'],['Additional reserve','$150,000','Policy assumption, not duplicate expenditure'],['Funding gap','$200,000','$400,000 less $200,000']])),
 sec('Test source, availability and allocation','The finance lead builds a dated funding bridge, using descriptions and evidence status rather than uploading financial documents here. For every source, record owner, currency, conversion assumption, restrictions, release date, competing commitments and conditions. Decide which confirmations must be handled securely by the responsible professionals outside this site.'),
 sec('Reusable evidence checklist','Output: a funding bridge and a gap-resolution task, not a “funding verified” badge.',bullets=['Separate reported wealth, liquid assets and committed project capital.','Tie every funding source to a date and authorised person.','List existing pledges, collateral and other ventures drawing the same money.','Cost the downside cash peak before setting the reserve.','Keep uncommitted borrowing and unverified self-reporting unresolved.','Decision: establish additional capital, reduce scope, stage rights or pause.'])
],[FIN],4,'A project funding bridge with dated evidence and remaining gap',['No partner solvency certification or collection of bank statements.'],scenario='fictional')

guide('case-territory','/cases/staged-industrial-services-territory/','Fictional case: a Dutch operator requests several states','A fictional industrial-services brand tests staged territory rights against delivery, support and partner investment.','case','relationship',['Netherlands','Federal'],[
 sec('The decision','Fictional scenario. A Dutch industrial-maintenance brand meets a capable regional operator seeking rights across several U.S. states. No U.S. unit has yet demonstrated repeat demand, local hiring or the proposed support cost. The request may be commercially reasonable to negotiate, but home-market success is not evidence that every requested territory can be served.'),
 sec('The overlooked fact','A multi-state map hides different customer clusters, travel times and account decisions. A national customer may procure centrally but require local dispatch. An online lead can come from a site outside the operator’s route. The partner may invest in equipment and training before there is enough density to use them.'),
 sec('Make rights and obligations specific','Draft staged rights around measured operating capability, customer validation and support capacity. State who can solicit, serve and invoice national accounts; who receives online leads; whether existing contracts are reserved; and how work crossing a boundary is allocated. Item12 is a useful territory-disclosure reference in a franchise structure; it does not create exclusivity by itself.',sids=[FG],table=(['Stage','Fictional commercial evidence','Unresolved legal task'],[['Initial area','One service cluster and named pilot customers','Review territory and sales-law scope'],['Further rights','Service quality, funded staff and supported demand','Review expansion commitments and disclosure updates'],['Delay','Documented permit, procurement or hiring obstacle','Review extension, notice and cure provisions'],['Exit/transfer','Protect customer continuity and invested equipment','Review state protections and agreement terms']])),
 sec('Protect both investments','The brand should not reserve a whole market indefinitely without support. The partner should not face an impossible opening timetable or lose investment automatically when a permit is delayed. Record objective milestones, dependencies, reporting, adjustment process and proposed cure time. Rights against the contracting brand do not guarantee protection from independent competitors; enforceability remains jurisdiction-specific.'),
 sec('Reusable territory checklist','Output: a territory principles sheet owned by the commercial lead before a binding development commitment.',bullets=['Identify the specific customer segment, operating base and service radius.','Separate own-unit development from authority to recruit subfranchisees.','Map national accounts, online enquiries, adjacent operators and cross-border jobs.','Price field support and travel for each stage.','Record evidence required for added rights and reasonable delay handling.','Have state relationship protections and contract enforceability reviewed; keep unresolved provisions visible.'])
],[FG,FR],4,'Staged territory principles and national-account allocation map',['Fictional commercial exercise; no assurance of exclusivity or enforceability.'],[RFR],scenario='fictional')

guide('case-e-nationality','/cases/singapore-subsidiary-e2-ownership/','Fictional case: a Singapore address does not settle E-2','A fictional Malaysian-owned group separates subsidiary incorporation from ultimate ownership, control and individual U.S. work.','case','immigration',['Malaysia','Singapore','Federal'],[
 sec('The decision','Fictional scenario. A Malaysian-owned group uses a Singapore subsidiary for regional contracts and assumes that the subsidiary can sponsor any manager for U.S. work as a treaty business. The expansion owner plans to stay abroad, but a technical manager may travel to train and supervise a U.S. operator.'),
 sec('The overlooked fact','The Department of State lists Singapore as an E-2 treaty country. That listing is a starting fact, not an enterprise or personal eligibility decision. Under8 CFR214.2(e)(7), enterprise ownership must be traced to ultimate individual owners as practicable. Incorporation, ultimate nationality, tax residence, managerial control and the proposed person’s duties are distinct facts.',sids=[E,TREATY]),
 sec('Draw ownership before choosing a route','Build a diagram using entity names or aliases and ownership percentages: ultimate owners → Malaysian parent → Singapore subsidiary → proposed U.S. entity. Add who appoints directors and who controls decisions. If an entity or individual fact is unknown, preserve it as unknown. A franchise or licensing agreement is not assumed to create an L-1 corporate relationship.'),
 sec('Build a people-mobility workstream','The E provisions separately address investment and the person’s investor or employee role. Describe each person’s actual U.S. activity, employer, authority, intended duration and work location. A business visit, hands-on service work, executive transfer and investor role require different analysis. Do not reorganise ownership or commit money merely because an educational worksheet highlights an issue.',sids=[E],table=(['Question','Evidence description only'],[['Who ultimately owns?','Ownership layers, percentages and nationality facts'],['Who controls?','Voting, appointment and management rights'],['Who will work?','Named role, employer and actual U.S. duties'],['What is invested?','Source, commitment, project use and conditions'],['What remains unresolved?','Treaty footnotes, personal eligibility and route-specific advice']])),
 sec('Reusable decision checklist','Output: an ownership diagram and people-mobility plan. No passport, bank record or immigration document upload is needed.',bullets=['Keep founder relocation optional if the founder will remain abroad.','Escalate mobility early if a named person is essential for feasibility.','Record ultimate nationality facts separately from subsidiary country.','Distinguish capital availability from a qualifying committed investment.','Assign the unresolved individual and enterprise questions to a responsible reviewer before travel or work commitments.'])
],[E,TREATY],5,'Ownership diagram and people-mobility questions',['No visa eligibility determination.','FAM and USCIS detailed guidance access could not be completed in this review; route-specific analysis remains unresolved.'],[RE],scenario='fictional')

guide('case-master','/cases/branch-operator-versus-master-franchise/','Fictional case: a French branch operator considers master rights','A fictional operator who runs branches well compares own-unit development with recruiting and supporting other owners.','case','commercial-feasibility',['France','Federal'],[
 sec('The decision','Fictional scenario. A French services brand wants one partner to build a U.S. network. The candidate has strong supervisors, client retention and multi-branch delivery. The candidate asks for master rights, including authority to recruit subfranchisees. There is no evidence yet of franchise sales administration, training for independent owners or a support office.'),
 sec('The overlooked fact','Running units and supporting independent owners are different capabilities. An area developer may open its own units under a development agreement. A master arrangement can add pre-sale and post-sale responsibilities for other owners. The federal definition of franchisor includes subfranchisors engaging in both kinds of activity; actual functions matter.',sids=[FR]),
 sec('Build the capability-and-cost matrix','The candidate and brand assign responsibilities before setting the royalty split. A percentage allocation without a service budget can leave continuing support underfunded.',table=(['Workstream','Own-unit developer','Master arrangement: additional work'],[['Delivery','Hire and supervise own operating teams','Support independent owner delivery'],['Recruitment','Recruit employees and managers','Recruit and assess prospective franchisees'],['Pre-sale','Participate in own transaction','Manage permitted sales, disclosure and records'],['Training','Train own teams','Train owners and their managers'],['Field support','Manage branches','Fund visits, issue resolution and monitoring'],['Economics','Unit margins and shared overhead','Recurring support budget and fee allocation']])),
 sec('Test continuing funding','Use an original illustrative support budget with separately labelled assumptions for staff, travel, training, localisation, systems and compliance work. Model a year with no new territory fee receipts. If continuing royalties do not fund promised support at the planned network size, revise the split, scope, minimum funding or rollout pace; do not assume endless upfront sales.'),
 sec('Reusable capability checklist','Output: a responsibility matrix with a role owner, evidence and annual cost for every promised function.',bullets=['Document which units the candidate itself will operate.','Mark who contracts with and supports each independent owner.','Identify sales, disclosure and local registration work before recruitment.','Separate initial training from recurring field support.','Test staff time at both a small network and a delayed rollout.','Decision: own-unit development first, smaller master scope, build capability or pause.'])
],[FR,FIN],1,'Capability-and-cost matrix for own-unit versus master responsibilities',['Commercial labels do not decide franchise-law obligations.'],[RFR],scenario='fictional')

guide('case-lease','/cases/lease-clock-before-opening/','Fictional case: rent starts before the restaurant can open','A fictional lease and delay model shows why rent commencement, permissions and customer receipts need separate dates.','case','premises-opening',['Federal'],[
 sec('The decision','Fictional scenario with no real address or local-law claim. A restaurant operator signs a lease with rent beginning1April. Fit-out is planned for two months and opening is assumed for1June. The team has not confirmed permitted use, design requirements or inspection sequence. The dates and all costs here are deliberately invented teaching assumptions.'),
 sec('The overlooked fact','The lease decides contractual payment dates subject to its actual terms. Authorities decide operating permissions under relevant rules. A landlord’s statement, insurer’s condition and regulator’s approval are different evidence. Every commercial lease must be read: do not assume it is triple-net, that taxes are included, or that additional charges follow a universal percentage.'),
 sec('The consequence of an illustrative delay','Assume base rent of$8,000/month and separately identified pre-opening team/utilities costs of$6,000/month. A three-month opening delay while these amounts continue adds$42,000 of cash use before considering debt, extra fit-out, food spoilage or other charges. This is $14,000 ×3 under the fictional assumptions, not a permit-delay forecast or total funding requirement.',table=(['Date or cost','What to record'],[['Possession','Access for survey, works and storage'],['Rent commencement','Actual clause and any conditions'],['Approvals','Agency, application, prerequisite and evidence'],['Opening','Permission plus operational readiness'],['Other occupancy amounts','Taxes, insurance, maintenance, utilities, deposit and reconciliation'],['Cash receipts','Customer start and collection timing']])),
 sec('Create a dependency plan before commitment','SBA explains that licenses depend on business activity and location. The project lead must identify an actual municipality, county, address, use and sector before relying on specific local explanations. Put use confirmation, design, landlord approval, works, inspections, utilities and food-operation tasks into a dependency graph; record responsible people and contingency dates.',sids=[LIC]),
 sec('Reusable lease-clock checklist','Output: a lease-date and permissions schedule with an explicit delay scenario.',bullets=['Ask the property lead to abstract payment, improvement and commencement terms.','Identify contingencies and extension rights for professional review.','Record what each landlord, authority and insurer document actually establishes.','Keep address-dependent tasks pending until an address is chosen.','Model cash monthly and avoid counting the same rent in both fit-out and delay reserves.','Decision: resolve conditions, change timing or premises, stage spending or pause.'])
],[LIC,FIN],5,'Lease-date abstraction and a dated pre-opening cash plan',['No named locality researched by this scenario.','Delay assumptions are fictional; lease interpretation and actual local approvals remain unresolved.'],scenario='fictional')

guide('case-supply','/cases/cleaning-product-us-supply/','Fictional case: the home-market cleaning product cannot simply ship','A fictional B2B cleaning brand compares a home-market pesticide product with a documented U.S. sourcing alternative.','case','products-supply',['Federal','Singapore'],[
 sec('The decision','Fictional scenario. A Singapore cleaning brand’s preferred disinfectant is treated, for this exercise, as a FIFRA-regulated pesticide product. The team wants the U.S. operator to use exactly the same branded bottle. No actual product, formulation or registration is identified, and this site does not decide whether a particular product is a pesticide.'),
 sec('The overlooked fact','EPA’s import guidance distinguishes lawful product status, producing-establishment requirements and Notice of Arrival paperwork. An establishment number is not a product approval. An unregistered pesticide cannot simply be imported for ordinary U.S. use by relying on foreign sale; EPA identifies specific import exceptions requiring separate conditions. The actual product and intended use must be assessed.',sids=[IMP]),
 sec('Compare the complete supply job','The operations and compliance leads can investigate two paths: establish a lawful import/supply route for the specified product, or validate an appropriate U.S. substitute. Compare intended use, label directions, application method, surface compatibility, client specification, training, storage and procurement continuity. A familiar smell or bottle colour is not a service-outcome specification.'),
 sec('Keep landed cost incomplete until the missing inputs arrive','Use a transparent worksheet: purchase cost + freight + insurance + customs/broker costs + applicable duties/tariffs + local handling + storage + compliance costs. Record currency, quantity, unit, quote date and importer. If a duty rate is unknown, the total remains incomplete. Do not substitute zero. Record minimum orders and lead times in the cash schedule.',table=(['Decision factor','Import path','U.S. substitute path'],[['Regulatory responsibility','Identify importer and actual product status','Confirm actual product and permitted use'],['Evidence','Composition, claims, label and supply records','Label, supplier record and compatibility trial'],['Economics','Landed costs and inventory financing','Delivered quote and minimum purchase'],['Consistency','Training and customer approval','Defined outcome and documented validation']])),
 sec('Reusable sourcing checklist','Output: an approved-for-investigation supply specification, not a declaration that a product may enter or be used.',bullets=['Identify the exact product and claims; leave category uncertain if unresolved.','Assign importer, supplier and operator responsibilities in writing.','Obtain current product/establishment and shipment evidence where applicable.','Check sector, state, worker and client-use constraints.','Pilot a substitute against objective performance and compatibility criteria.','Update the operating manual only after responsible technical and compliance review.'])
],[IMP,OSHA],5,'A supply specification and import-versus-substitute comparison',['No actual EPA product determination, import authorisation or current tariff calculation.'],[RI],scenario='fictional')

# Real cases: narrow historical narratives from complete orders. No allegations are rewritten as trial findings.
guide('case-burgerim','/cases/burgerim-entity-default-judgment/','Burgerim: what the entity default judgment actually ordered','A real January2024 federal entity judgment illustrates why selling promises and practical support need evidence.','case','sales-disclosure',['Federal'],[
 sec('What the document establishes','Real case, historical document review. On19January2024, the Central District of California entered a default judgment against Burgerim Group USA, Inc. and Burgerim Group, Inc. The order followed their default; it is not a contested merits trial. Page3 separately notes an earlier order as to Oren Loni. The entity order bars the entity defendants from U.S. franchise sales and imposes$7,750,000 in civil penalties and$48,476,689 for consumer redress.',sids=[BUR]),
 sec('Keep order, payment and present status separate','Those are judgments entered, not evidence that money was collected or paid to buyers. The official FTC case index still carries a Pending label and a January2024 last-update date. This page explains the identified entity order; it does not certify the complete present docket, a recovery rate or any current business’s conduct.',sids=[BUR,BURI]),
 sec('A management lesson for an expanding brand','The order also addresses misrepresentations about income, payback time, training, assistance and other material facts. A brand owner who delegates U.S. sales still needs an owner for the evidence behind those promises. Treat a promised support capability as a budgeted delivery obligation, not a brochure phrase.',sids=[BUR]),
 sec('Prepare a claims-and-capability register','Original preparation exercise: take each proposed U.S. sales statement and assign its author, factual support, applicable audience, approved form and review date. For an opening-time statement, separate location selection, customer procurement, fit-out, permissions and staff readiness. For a support statement, name the actual team, travel budget and response capacity. Keep this exercise separate from approved FDD representations.'),
 sec('Reusable evidence checklist','Output: a sales-claim register before materials or scripts are used.',bullets=['Retain each brochure, website version, event slide and spoken-script approval.','Record precisely what the evidence supports and what it does not.','Do not convert a private planning calculator into a prospect earnings promise.','Assign support delivery and review responsibilities to named roles.','Record customer complaints and refund obligations against actual contract terms.','Use current federal/state rules for today’s transaction; this judgment is not an automatic penalty schedule.'])
],[BUR,BURI],1,'Sales-claim and promised-support register',['Historical entity judgment only; no recovery proof or full current docket certification.','The case does not establish automatic sanctions for every violation.'],scenario='real')

guide('case-tower','/cases/tower-cleaning-earnings-and-records/','Tower Cleaning: a historical service-franchise consent decree','A real1996 commercial-cleaning settlement connects earnings claims, disclosure records and evidence preservation.','case','sales-disclosure',['Federal'],[
 sec('A service-business case with a bounded lesson','Real case, historical document review. The official FTC record for Tower Cleaning Systems, Inc. and David A. Gansky links a1996 consent decree in the Middle District of Pennsylvania. The decree states that settlement occurred without adjudication of disputed issues and without an admission of liability. Its terms include$50,000 consumer redress and restrictions on misrepresenting franchise sales, income or profits.',sids=[TOWER,TOWERI]),
 sec('What this does and does not prove','The complete decree and appendices were read for this page. Its disclosure and earnings-document references use the pre-2007 Franchise Rule and Uniform Franchise Offering Circular framework. They are historical, not instructions for a current FDD. The order itself does not establish that redress was collected, and this page makes no claim about later operations or later docket activity.',sids=[TOWER]),
 sec('The reusable operating lesson','A commercial-cleaning brand needs a way to connect marketing statements to the underlying contracts and operating facts. Gross account billings do not identify labour hours, travel between buildings, rework, supplies, customer churn or payment delay. A portfolio transferred to a new operator can also change staffing and route density. These are original business-analysis questions, not findings about Tower beyond the identified decree.'),
 sec('Build an account-cohort worksheet','For any proposed operational comparison, define location, period, unit age, owner/manager participation, service mix and included accounts. Track accounts lost or excluded and document why. Keep an evidence source and reviewer next to every number. Do not infer profitability from a customer’s contract value or treat a hand-selected cohort as the likely result for a new operator.'),
 sec('Reusable evidence checklist','Output: a cleaning-account economics worksheet and a record-retention assignment.',bullets=['Separate contracted revenue, invoiced revenue and cash actually received.','Record site time, travel, supervision, equipment and quality costs.','Define the cohort and all exclusions before comparing units.','Record the dates and limits of any customer or operator evidence.','Route proposed prospect-facing financial statements through current FDD and legal review.','Preserve a readable record of the source, calculation and approved statement.'])
],[TOWER,TOWERI,FIN],3,'Account-cohort worksheet and evidence-retention ownership',['Historical consent resolution without admission; current rules require separate analysis.','No payment or current-business finding is made.'],scenario='real')

guide('case-qargo-hold','/cases/qargo-license-label-review/','Qargo Coffee: entered-order verification pending','Research record held from publication while the actual signed order and current procedural record are reconciled.','case','sales-disclosure',['Federal','California'],[
 sec('Why this record is not published','The official case index describes the FTC allegations and links a proposed order dated16October2024. The December2024 FTC litigation status report records a stipulated order entered17October2024. The filed proposed PDF has a blank judicial signature/date. Metadata saying Pending is not sufficient to disregard the later official report.'),
 sec('Research completed','The complete operative proposed-order pages1–16 were read. Those are not represented as the actual entered text. The report supports the entry date it records; the actual signed order and any later docket developments remain outstanding.'),
 sec('Release condition','Obtain and read the entered order, reconcile materially different terms and check later procedural documents before a final narrative is published. Preserve allegations as allegations; a proposed rescission term is not automatic repayment of every dollar invested.')
],[Q,QP,QR],1,'A source-conflict task and entered-order retrieval request',['Publication blocked: entered signed order and later docket check incomplete.'],status='blocked',scenario='real')
guide('case-octoclean-hold','/cases/octoclean-order-review/','OctoClean: full-order source review pending','Research record held because the official consent-order PDF could not be read.','case','sales-disclosure',['California'],[sec('Why this record is not published','The DFPI September2023 enforcement summary identifies an OctoClean consent order. The official PDF returned HTTP403 in this review. A search excerpt and summary cannot replace reading its complete operative terms.'),sec('Release condition','Read the complete official consent order and check for subsequent relevant orders. Separate recitals, admissions, stipulated obligations and actual performance. No penalty, current violation or clearance claim is published from this incomplete record.')],[OCT],5,'Source-access and later-order review task',['Publication blocked: complete order inaccessible.'],status='blocked',scenario='real')

# Industry guides: specific operating decisions plus clearly separated recommended business practice.
guide('industry-cleaning','/industries/commercial-cleaning/','Expand a commercial-cleaning business with evidence from the route','Test supervision, account quality, customer payment and delivery economics before offering U.S. rights.','industry','commercial-feasibility',['Federal'],[
 sec('Start with the account and the route','For an established cleaning company, the useful unit is often an account cluster served by a team and supervisor, not a retail outlet. Compare customer type, usable service hours, site access, travel, recurring frequency and contract length. A home-market annual contract is evidence of delivery there; it does not establish U.S. demand, labour availability or procurement acceptance.'),
 sec('Model the costs that a branch manager does not remove','Assign responsibility for estimating labour, winning bids, replacing absent staff, responding to complaints and managing receivables. Price dedicated management and quality supervision before a royalty. Then test account concentration: losing one large building can leave paid supervisory time, vehicles and route gaps while the revenue disappears.'),
 sec('Separate law, customer conditions and practice','OSHA identifies cleaning-industry chemical, equipment and workplace hazards and links applicable general-industry standards. Build the actual task/product safety review with the responsible employer. A customer’s insurance certificate, background-screening or service-level requirement is a procurement condition unless separately required by law; record its source and cost.',sids=[OSHA]),
 sec('Use an original fictional pilot','Fictional example: investigate three nearby office buildings rather than assume a national rollout. Record bid process, required service times, equipment storage, staffing cover, client sign-off and collection terms for each. Unknown travel time or wage evidence remains missing; it does not improve a market score.'),
 sec('Prepare before the next bid','Output: an account-level pilot brief owned by the COO with the finance lead.',bullets=['Record client type, tender date, contract renewal and termination provisions.','Map service hours, travel, supervision and emergency cover.','Obtain insurance and customer-procurement requirements separately from law.','Track invoice acceptance, disputes and actual receipt dates.','Define who receives and serves national accounts.','Test a paid, lawfully arranged pilot without implying that it authorises franchise offers.'])
],[OSHA,FIN],2,'Account-cluster pilot and supervision-cost brief',['No location-specific wage, tax, customer demand or safety clearance.'])

guide('industry-facilities','/industries/facilities-services/','Separate the facilities contract from the work that needs a license','Map each service, employer and subcontractor before transferring a facilities-management model.','industry','premises-opening',['Federal'],[
 sec('One customer contract can contain many regulated activities','Facilities services can include cleaning, planned maintenance, access systems, pest control, landscaping and repairs. Describe the exact tasks rather than presume that a facilities brand license permits every activity. Map what the partner performs, subcontracts and merely coordinates. Local professional, contractor and sector requirements can change that allocation.'),
 sec('Build the service-level responsibility map','A service-level agreement describes contracted performance: response time, completion evidence, exclusions, escalation and credits. Assign who dispatches, approves additional work, invoices, handles emergencies and bears rework. Customer procurement may demand specific insurance, references or approved subcontractors. Those contractual requirements deserve a separate category from government rules.'),
 sec('Investigate actual permit and licence triggers','The SBA directs businesses to licenses according to activity and location. Start with the named state, municipality, county and worksite; record the authority for each trade or operating question. A subcontractor’s own licence does not resolve every duty of the principal contracting or employing entity.',sids=[LIC]),
 sec('Fictional operating example','A fictional partner wins one multi-site customer with 60-day invoice terms. The partner must pay technicians and subcontractors earlier, while the customer can dispute incomplete service evidence. The relevant test is both gross margin and dated cash collection. Model the national customer’s failure separately from a broad market-sales percentage.'),
 sec('Reusable preparation checklist','Output: a service-by-service operating and procurement matrix.',bullets=['Break the offer into tasks, locations and contracting parties.','Record accountable employer and competent operating lead.','Identify public authorisation, customer condition and insurer condition separately.','Price emergency response, subcontractor management and service credits.','Trace national-account allocation and cross-territory work.','Collect evidence before promising the full service bundle.'])
],[LIC,FIN],5,'Facilities task, licence and customer-condition matrix',['No universal facilities-services licence analysis.'])

guide('industry-pest','/industries/pest-control/','A pest-control brand needs an operating certification plan','Check people, products and operating jurisdictions before estimating a U.S. pest-control launch.','industry','products-supply',['Federal'],[
 sec('Begin with the application work','A pest-control partner needs more than the right to use a name. List target pests, treatment method, sites, products and the people applying or supervising them. Distinguish product authorisation from applicator certification and any business licence. Home-country training can be useful evidence of capability but does not itself establish U.S. authorisation.'),
 sec('The federal starting point and local extension','EPA explains that restricted-use pesticide applicators or supervisors need certification under relevant rules and that state, territorial and tribal authorities administer certification. Many states have broader requirements for commercial work. Investigate each operating jurisdiction and category before assigning a technician or assuming cross-state portability.',sids=[PEST]),
 sec('Make route economics match service obligations','Recurring service contracts can create route density, but callbacks, emergency jobs, seasonal demand, storage and customer access affect capacity. A large territory with scattered accounts may consume the supervisor’s time. Record insurance requested by customers and actual spill, vehicle and product-use responsibilities; do not treat an insurance quote as regulatory approval.'),
 sec('Fictional decision','A fictional European brand proposes importing a familiar treatment product and starting in two neighbouring states. Split the launch into two workstreams: lawful product/import review and each state’s people/business authorisations. A U.S.-sourced product may change inventory logistics but does not erase applicator obligations.'),
 sec('Reusable launch checklist','Output: a product/person/jurisdiction map.',bullets=['Identify actual products and label-directed sites/uses.','Name the certifying authority for each area and category.','Record who is qualified and what supervision is required.','Assign storage, transport, customer notice and incident questions.','Obtain route, seasonality and callback evidence.','Keep unsupported certification, fee and insurance inputs unresolved.'])
],[PEST,IMP,LIC],5,'Pest-control certification and supply workstream',['No state certification or specific product conclusion.'],[RP,RI])

guide('industry-industrial','/industries/industrial-maintenance/','Validate industrial-maintenance delivery before selling territory','Price competent supervision, downtime commitments and site safety against a narrow first service cluster.','industry','employment',['Federal'],[
 sec('Define the work more narrowly than the brand','Industrial maintenance may range from inspection to machine servicing, electrical work and process-critical repair. Document the equipment, task boundaries, customer qualification process and escalation rights. Professional or trade licensing, site-access rules and customer engineering approval can determine what the partner may actually deliver.'),
 sec('Hazardous energy is an operating workstream','OSHA’s general-industry overview explains hazardous-energy risks in servicing and maintenance and points to29 CFR1910.147. For covered work, the responsible employer needs appropriate energy-control procedures and training. Identify actual tasks and host-contractor interfaces; this guide does not decide exemptions or replace the customer-site procedure.',sids=[LOTO]),
 sec('Test the economics of a response promise','A four-hour response promise is a staffing, geography and spare-parts decision. Model on-call pay, specialist cover, travel, calibration, tools, insurance and subcontractors. Separate a customer’s production loss exposure from the service fee. Record liability and service-credit negotiation as a contract workstream with financial review.'),
 sec('Fictional first-market test','A fictional Dutch brand chooses one industrial corridor for customer interviews and a permitted pilot. The team asks what suppliers must demonstrate before a bid, how shutdown windows are scheduled and who approves a new technician. A national population total is not evidence that those procurement gates can be passed.'),
 sec('Reusable evidence checklist','Output: a first-corridor delivery and qualification brief.',bullets=['List specific assets and tasks within scope.','Document competencies, local trade questions and supervision.','Map each customer’s procurement, safety and insurance requirements.','Model response time using real dispatch and travel assumptions.','Separate recurring maintenance revenue from one-off shutdown projects.','Fund support and specialist escalation without relying on territory-sale fees.'])
],[LOTO,LIC,FIN],2,'Industrial-service scope, safety and response-capacity brief',['Task-specific OSHA, state-plan and trade scope remains to be reviewed.'],[RL])

guide('industry-technical','/industries/technical-services/','Test whether technical decisions can travel without the founder','Document authority, competence and escalation for a U.S. technical-services partner.','industry','commercial-feasibility',['Federal'],[
 sec('Find the decisions still owned by the founder','A technical-services company can have branch managers while the owner still approves every unusual job, specification, supplier substitution or warranty dispute. List those decisions and record frequency, response time and consequences. The goal is an operating responsibility map, not a questionnaire score proving that knowledge is transferable.'),
 sec('Distinguish experience from authorisation','Prepare a task list identifying whether each activity is inspection, advice, design, installation, repair or certification. The actual state, profession and worksite determine operating requirements. SBA’s location/activity approach is a starting point; neither a brand licence nor foreign professional status settles U.S. authority.',sids=[LIC]),
 sec('Price the escalation channel','Record support time for quotations, complex faults, documentation, audits and client meetings. If the U.S. manager must wait overnight for the European founder, a response promise can fail even with capable field staff. Cost a backup decision maker and define which decisions stay with the brand, partner and appropriately authorised professional.'),
 sec('Fictional validation task','For a fictional German testing-services brand, choose ten historic exception jobs. Ask a proposed manager to produce a decision and escalation record using sanitised facts. Compare decisions with the responsible technical lead. This exercise tests documentation gaps; it does not confer professional competence or guarantee future outcomes.'),
 sec('Reusable preparation checklist','Output: a competence-and-decision matrix.',bullets=['Map owner-only technical, pricing and customer decisions.','Name the accountable decision maker and qualified backup.','Record evidence of training, observed performance and limits.','Separate customer accreditation from government authorisation.','Price remote and in-person escalation.','Define a bounded U.S. pilot before broad rights are granted.'])
],[LIC,FIN],0,'Technical decision authority and owner-dependence map',['No professional credential or regulatory approval is issued.'])

guide('industry-it','/industries/it-services/','Allocate access, support and incident duties in an IT-services model','Check who controls customer data and service continuity before a U.S. partner receives systems access.','industry','ip-data',['Federal'],[
 sec('Start with the service and access map','IT support, managed services, software implementation and training have different access needs. Record who contracts with the customer, whose staff access systems, where access occurs, what data is involved and who authorises changes. Separate the brand’s software rights from a customer’s licence and security permissions.'),
 sec('Build a usable responsibility schedule','NIST provides small-business guidance on cybersecurity risks, incident response, cloud security and other topics. Use it as a preparation reference. It is not a universal law, an endorsement or a certification of your service. Actual customer, public-contract, sector and privacy requirements need their own evidence and scope.',sids=[NIST]),
 sec('Price the support window','A U.S. customer may expect service while the parent’s team sleeps. Cost on-call cover, escalation, third-party licences, secure onboarding/offboarding, backups, incident exercises and client reporting. Clarify who funds emergency work and who can communicate externally after an incident. Do not promise “24/7 support” without staffing and supplier commitments.'),
 sec('Fictional pilot','A fictional Southeast Asian managed-service brand gives one U.S. partner a limited customer support role. Before live access, the team rehearses a departed technician’s account removal and a suspicious-login report using a test environment. Record completion as an exercise, not proof of legal compliance or absence of security risk.'),
 sec('Reusable preparation checklist','Output: an access-and-incident responsibility schedule.',bullets=['Record customer, provider and partner entities and actual data paths.','Define minimum necessary access and named approvers.','Map breach/incident escalation and contractual deadlines without inventing a universal deadline.','Record cross-border privacy questions and sector restrictions as unresolved until reviewed.','Budget licence, security and coverage costs per customer.','Test service continuity if the parent or partner is unavailable.'])
],[NIST,FIN],1,'IT data-access and incident responsibility schedule',['No comprehensive federal/state or cross-border privacy assessment.'])

guide('industry-training','/industries/business-training/','Distinguish business training from regulated credentials','Prepare a U.S. training model around delivery rights, instructor capability and claims that can be supported.','industry','commercial-feasibility',['Federal'],[
 sec('Describe the actual learning service','Business training may mean corporate workshops, technical instruction, employee assessment or a course marketed as qualifying someone for an occupation. State exactly what learners receive. A certificate of attendance, private brand certification, licence to practise and recognised professional credential are different things.'),
 sec('Investigate the relevant activity and location','SBA’s general licensing guidance ties requirements to the activity and operating location. Record where teaching, recruitment, assessment and customer contracting occur. If training touches a regulated occupation, childcare, healthcare or postsecondary education, move the relevant operating review ahead of sales promises. Do not imply that licensing a syllabus is enough.',sids=[LIC]),
 sec('Make the content and delivery rights usable','Record ownership and permitted use of slides, software, recordings, marks, learner materials and translations. Name who updates technical content and who can approve instructors. A well-run home-market branch may rely on the founder’s teaching or sales reputation; test whether another instructor can deliver the defined outcome.'),
 sec('Fictional economics exercise','A fictional European B2B training brand tests one paid corporate workshop through a properly reviewed arrangement. Record customer procurement, instructor preparation, venue/platform costs, travel, materials, cancellation terms and collection date. Do not multiply a full classroom’s gross revenue by every working day and call the result likely profit.'),
 sec('Reusable preparation checklist','Output: a course-rights and delivery-capability factsheet.',bullets=['Describe the credential or attendance evidence precisely.','Identify sector or education authorisation questions before promotion.','Record intellectual-property rights and revision ownership.','Observe instructor delivery and assessment using stated criteria.','Price realistic utilisation, preparation and customer acquisition.','Keep customer outcome claims tied to actual evidence.'])
],[LIC,FIN],1,'Training rights, claims and delivery-capability factsheet',['No professional or education authorisation determination.'])

# Practical decision guides.
guide('guide-management','/us-expansion/management-independence/','Can the business deliver without the owner every day?','Map real decisions and evidence before treating branch managers as proof that the model transfers.','decision','commercial-feasibility',[],[
 sec('A manager title is a starting fact','Management independence is the ability to make and deliver the important decisions when the owner is absent. Investigate sales, pricing, technical exceptions, key accounts, supplier negotiations, recruitment, quality and cash authorisations. A business can perform daily operations while still relying on the owner for the exceptions that protect margin and customers.'),
 sec('Use a responsibility map with evidence','For each responsibility, record accountable role, day-to-day decision maker, backup, authority limit and the most recent observed example. Distinguish a manual being written from a manager successfully using it. Record unresolved gaps instead of converting answers into a transferability score.'),
 sec('Fictional preparation exercise','In a fictional facilities company, the COO covers service delivery but the owner closes every contract above a chosen internal limit. The U.S. plan needs a local sales authority, realistic procurement time and parent support. The management payroll and support budget must include the people who would replace that work; the SBA finance guide supports the cost/cash discipline, not a required manager salary.',sids=[FIN]),
 sec('Test a bounded absence','Choose an internal, reversible exercise such as a planned week with documented escalation rules. Select ordinary and exception tasks in advance. Record what happened, who decided, delays, rework and customer effect. This is recommended business practice, not proof that U.S. delivery or legal obligations are satisfied.'),
 sec('Prepare the next decision','Output: an owner-dependence map before selecting a partner model.',bullets=['List recurring decisions and consequential exceptions.','Name the role and backup with actual authority.','Record evidence date, limits and unresolved dependencies.','Cost replacement management and parent support separately.','Re-test after a change in offer, staffing or customer mix.','Choose further documentation, a smaller pilot, added capability or a pause.'])
],[FIN],0,'Responsibility map with owner dependencies and evidence dates',['Business preparation only; no statutory readiness threshold.'])

guide('guide-models','/us-expansion/area-developer-vs-master/','Area developer or master operator: who will do the extra work?','Compare contracting, payments, recruitment and ongoing support before setting U.S. network rights.','comparison','classification',['Federal'],[
 sec('Decide functions before labels','An own-unit operator delivers services in its own business. An area developer undertakes to open its own units over time. A master arrangement can authorise the recruitment and support of subfranchisees. An area representative may assist recruitment or support while the brand remains the contracting franchisor. Distribution and IP licensing need their own goods, payments and control facts.'),
 sec('Map three kinds of flow','Draw contracts, money and operating support separately. Who grants rights to the unit operator? Who collects initial and continuing payments? Who provides initial training, approves operators, supports bids, monitors quality and handles disputes? The definition in16 CFR436.1(k) includes subfranchisors performing pre-sale and post-sale functions; allocation in a contract does not erase regulatory duties.',sids=[FR]),
 sec('Compare capability and funding','A partner may run excellent branches while lacking the staff and systems to recruit independent owners. List the extra roles and cost them before offering broad rights. Model the recurring support office using the revenue it can actually retain after the brand split, tax assumptions and obligations; treat unknown withholding as unresolved.'),
 sec('Fictional decision','A fictional brand expects the first partner to operate two branches, then recruit others. Phase1 own-unit evidence should not automatically satisfy Phase2 recruitment and support readiness. Write a separate decision gate with ownership, funding, sales-law review and support-capability evidence.'),
 sec('Preparation checklist','Output: a responsibility and payment diagram.',bullets=['Identify every contracting and fee-receiving entity.','Separate own units from independent operator recruitment.','Assign pre-sale records and post-sale support.','Budget field visits, training, systems and local compliance work.','Test a delayed network and no new upfront fees.','Record unresolved federal and state definitions, disclosure and exemption questions.'])
],[FR,FIN],1,'Contract/payment/support diagram',['No label-based franchise classification or allocation of legal liability.'],[RFR])

guide('guide-pilot','/us-expansion/b2b-first-market-validation/','What evidence would justify the first B2B market?','Use procurement and delivery evidence to narrow a market before committing a territory.','decision','commercial-feasibility',[],[
 sec('Match the customer buying process','Define the customer type, specific service, expected contract, procurement gate and service radius. Commercial regions are comparison tools, not legal jurisdictions. A large metro population does not establish demand for a specialised maintenance team or acceptance of a foreign brand.'),
 sec('Separate three evidence levels','An interview records a stated need. A tender invitation records a procurement opportunity. A signed customer contract records obligations, subject to its actual terms; it still does not establish profitable delivery or payment. Record the date, source, limitations and what observation would change the next decision.'),
 sec('Use a transparent comparison','Choose criteria before seeing scores: customer fit, sales cycle, staffing, route density, support access, operating requirements and cash terms. Let the team set weights. Keep unknown inputs visible and exclude a total ranking when a critical criterion lacks evidence; missing permit cost or insurance cannot become a favourable zero.'),
 sec('Fictional test','A fictional pest-control brand compares one dense office cluster with a larger dispersed territory. It interviews buyers, checks actual service categories and obtains local staffing and insurance evidence. The dense cluster can be easier to test, but that is a hypothesis pending evidence rather than a published “best market” claim.'),
 sec('Preparation checklist','Output: a market shortlist with the smallest useful validation activity.',bullets=['State the customer segment and proposed operating boundary.','Record demand evidence separately from home-market assumptions.','Identify actual city, county, state and address-dependent tasks.','Quote costs with source, date, unit and scope.','Name the person, budget and date for the next validation.','Review law before offers, employment, imports or opening commitments.'])
],[LIC,FIN],2,'Market comparison with unknowns and a validation task',['No ranking, search-demand statistics or unsourced cost averages.'])

guide('guide-receivables','/us-expansion/b2b-receivables-and-runway/','A profitable service contract can still consume cash','Map invoicing, acceptance and collection before deciding how much working capital a U.S. unit needs.','decision','commercial-feasibility',[],[
 sec('Profit and cash answer different questions','For an accrual-based operating model, service revenue may be recorded before receipt. Payroll, materials and subcontractors can require earlier payment. SBA explains cash versus accrual accounting; the project needs a dated cash schedule alongside its operating-profit model.',sids=[FIN]),
 sec('Work back from the customer payment trigger','Read the proposed contract: when can an invoice be submitted, what evidence must accompany it, who approves it, when does the payment clock start and what disputes can defer payment? A nominal30-day term may start after acceptance rather than after the technician attends. Model the actual process instead of inserting a universal receivables ratio.'),
 sec('Fictional cash bridge','Fictional example: the first month’s service generates$80,000 in invoices but no cash yet. Payroll and other payments due that month total$65,000. The operating budget alone cannot tell whether capital covers those dates. Add deposits, tax payments, equipment, financing receipts and later collections to a dated flow; do not count the same payroll again in a generic reserve.'),
 sec('Stress concentration and delay','Run downside, base and upside assumptions explicitly. Change customer start date, collection delay, dispute rate and staffing commitments as separate drivers. A large national account can improve density while increasing exposure to a single approval chain. A supplier credit term is financing only if it is actually available on stated conditions.'),
 sec('Preparation checklist','Output: a dated receivables and funding schedule.',bullets=['Record service, invoice, acceptance and expected receipt dates.','Link labour and supplier payments to actual due dates.','Separate refundable deposits, expenditure and retained liquidity.','Mark uncommitted financing and unknown taxes as unresolved.','Derive peak funding from cumulative cash flows.','Assign the next evidence update to the finance lead.'])
],[FIN],3,'Dated cash-flow schedule and peak funding need',['Illustrative amounts are fictional; no customer collection forecast.'])

guide('guide-national-accounts','/us-expansion/national-accounts-and-territories/','Who owns the national account when local partners deliver?','Allocate selling, contracting, service, payment and credit before promising territorial rights.','decision','relationship',[],[
 sec('A customer can buy nationally and receive service locally','A facilities or technical-services customer may negotiate centrally while operations occur in several partner territories. Separate lead ownership, contracting authority, service obligation, invoice recipient and margin allocation. “Exclusive territory” alone does not answer those questions.'),
 sec('Write an account-allocation schedule','Define reserved existing accounts, newly won national accounts, local branches of national buyers, online enquiries and jobs straddling boundaries. Include response, referral and dispute processes. The schedule should explain who approves pricing and how local delivery costs are considered. In a franchise, territory disclosures and terms need to align; the FTC guide’s Item12 discussion is a reference point.',sids=[FG]),
 sec('Fictional overlap','A fictional Dutch maintenance partner wins a customer whose headquarters is inside its area but whose first job is elsewhere. Another partner has local capacity. Compare a referral fee, local-service payment and central contract arrangement as commercial options; none is assumed lawful or enforceable without relevant review.'),
 sec('Protect service continuity and investment','Budget sales effort, equipment and training fairly. Define what happens if one operator cannot meet a national service obligation or an account changes scope. Avoid promising protection from independent competitors or suggesting that a contractual reservation overrides non-waivable local relationship rules.'),
 sec('Preparation checklist','Output: an account-allocation matrix before territory negotiation.',bullets=['Classify accounts by actual contracting and service location.','Separate customer acquisition, fulfilment and collection.','Record channel, referral and pricing responsibilities.','Document expense and revenue allocation with an example.','Identify dispute, cure and continuity questions for review.','Make the disclosure and agreement consistent with the intended process.'])
],[FG,FR],4,'National-account allocation matrix',['No competition-law or territory-term enforceability opinion.'],[RFR])

guide('guide-partner','/us-expansion/partner-due-diligence-evidence/','Build a partner evidence file without pretending to certify a person','Separate capability, available capital, records and unresolved questions before granting U.S. rights.','decision','commercial-feasibility',['Federal'],[
 sec('Evidence should answer a particular decision','The objective is to know what the candidate can fund and perform, what commitments it is taking and what still requires investigation. Use entity identity, authority, operating history, management capacity, accessible project capital, references and delivery evidence. Self-reported answers remain self-reported until the responsible person records what was checked and when.'),
 sec('Set lawful and proportionate scope','Do not collect passports, personal court files, bank statements or confidential customer contracts through this educational site. Describe the evidence and its custodian. If sensitive diligence is justified, use the appropriately authorised professional and secure process outside this tool. Record consent and access scope where applicable.'),
 sec('Court coverage is not one checkbox','PACER’s Case Locator is a national federal court index, including district, appellate and bankruptcy cases. State and local courts, administrative proceedings, arbitration and foreign records require separate scope decisions. An empty search is not proof that there are no disputes, nor does an allegation establish misconduct.',sids=[PACER]),
 sec('Fictional evidence decision','A fictional British facilities candidate reports ample wealth but leaves project allocation and supervisor availability unclear. Record separate tasks: dated capital-allocation confirmation, references for comparable delivery, and the named manager’s competing commitments. Do not improve a score because one field is blank.'),
 sec('Preparation checklist','Output: an evidence register with custodian, date, limit and next action.',bullets=['Confirm entity name, identifiers and signing authority.','Separate net worth, liquidity, conditions and project allocation.','Observe relevant management and operating capability.','Document reference scope and contradictory evidence.','Record court systems, names searched, date and procedural outcomes.','Decide whether to investigate further, revise scope, run a pilot or pause.'])
],[PACER,FIN],4,'Partner evidence register',['No character, solvency, funding or compliance certification.'],[RC])

guide('guide-fdd-comparison','/us-expansion/compare-fdd-for-management-run-model/','Compare FDD evidence against the model your team will actually operate','Use entity, year, management duties and cohort limits to avoid a misleading comparison.','decision','sales-disclosure',['Federal'],[
 sec('Compare documents before comparing numbers','A Franchise Disclosure Document describes a particular seller and offering as of a particular issue or amendment date. Record entity, brand, year, state addenda, source URL and transaction scope. Do not mix one brand’s current fee table with another year’s financial results or assume a domestic owner-operated cohort matches a foreign brand’s management-run model.'),
 sec('Read management obligations alongside support','Item15 concerns participation in actual operation; Item11 describes assistance and training; Item12 addresses territory. A manager-run assumption needs evidence from the actual offer and agreement. A reviewer should check all23 items, not only the selected comparison fields. The FTC guide explains these disclosure subjects; it is not an endorsement of an offering.',sids=[FG]),
 sec('Use the comparison as an evidence workspace','Capture Items5–8 costs and sourcing;11–12 support and territory;15 participation;17 renewal, termination, transfer and disputes;19 any financial performance representation;20 outlet cohort and contacts;21 seller financial statements. Missing information remains missing, and automated extraction requires checking against the document.'),
 sec('Fictional cohort problem','A fictional service brand shows revenue from established units, while the team plans a new territory with a dedicated manager. Record cohort age, excluded units, service mix, owner effort and costs absent from revenue. Do not convert the number into a profit estimate or into a prospect-facing representation.'),
 sec('Preparation checklist','Output: a sourced, versioned FDD comparison worksheet.',bullets=['Link the actual source and retain issue/amendment dates.','Record what each cited item says, not a guessed blank.','Check owner/manager participation in the offered model.','Record cohort definition, exclusions and limitations.','Keep financial statements separate from unit performance.','Assign unresolved interpretation and legal questions before commitment.'])
],[FG,FR],3,'Versioned FDD evidence comparison',['No FDD document extraction is published or deemed verified automatically.'])

guide('guide-bid','/us-expansion/federal-service-contract-bid-cost/','Will a federal service contract change your labour cost model?','Identify covered wage and fringe obligations before reusing private-customer bid economics.','decision','employment',['Federal'],[
 sec('Check contract coverage first','The Department of Labor’s Service Contract Act guidance addresses covered federal and District of Columbia service contracts performed through service employees, subject to exceptions. For covered contracts over$2,500, applicable wage determinations and fringe benefits matter. A private customer’s tender is not automatically a federal service contract.',sids=[DOL]),
 sec('The budget needs the actual solicitation','Obtain the solicitation, incorporated clauses, wage determination, job descriptions, place of performance and any predecessor collective bargaining facts. Map actual duties to the relevant classifications. Do not price from a generic national minimum wage or assume a foreign company’s existing hourly rate is relevant.'),
 sec('Separate obligations from bid conditions','An agency or prime contractor may also require insurance, registration, financial capacity, references, security controls and reporting. Record each as a contract/procurement condition or a sourced legal requirement. The label matters because evidence, remedy and responsible role can differ.'),
 sec('Fictional bid review','A fictional cleaning partner expects one supervisor to cover several sites and uses its private-office bid template. The revised schedule must test the actual contract’s labour categories, benefits, staffing periods, travel and reporting. No wage amount is supplied here; without the relevant determination, the bid remains incomplete.'),
 sec('Preparation checklist','Output: a solicitation-to-cost checklist owned by the bid and payroll leads.',bullets=['Record buyer, contract type and place of performance.','Identify applicable coverage, exceptions and clauses.','Obtain current wage determination and relevant predecessor facts.','Map worker duties and price wages, benefits and reporting.','Test payment timing and start-up funding.','Do not commit a bid while critical wage or staffing inputs remain unknown.'])
],[DOL,FIN],3,'Federal service-contract labour-cost review',['No specific solicitation, wage determination or exemption decision.'],[RS])

# Reuse shared federal authorities and rules rather than maintain independent copies.
shared={'pr-definition':'fed-definition','pr-guide':'fed-compliance','pr-e-nationality':'fed-e2','pr-treaty-countries':'fed-treaties','practice-relationship-facts':'fed-relationship-definition','practice-e-ownership':'fed-e2-nationality'}
sources=[s for s in sources if s['id'] not in shared]
rules=[r for r in rules if r['id'] not in shared]
import re
def spacing(text):
 text=re.sub(r'([A-Za-z])(?=\d)',r'\1 ',text)
 text=re.sub(r'(\d)(?=[A-Za-z])',r'\1 ',text)
 text=re.sub(r'([A-Za-z])(?=\$)',r'\1 ',text)
 return text
def remap(obj,key=''):
 if isinstance(obj,list):return [remap(x,key) for x in obj]
 if isinstance(obj,dict):return {k:remap(v,k) for k,v in obj.items()}
 if isinstance(obj,str):
  if key in ('sourceIds','ruleIds'):return shared.get(obj,obj)
  if key in ('title','description','paragraphs','bullets','heading','headers','rows','practicalOutput','limitations','label'):return spacing(obj)
 return obj
cases=remap(cases);guides=remap(guides);rules=remap(rules)
# Read current fetch evidence instead of equating fetch and substantive-review time.
fetch_log=json.loads(pathlib.Path('research/practice/fetch-log.json').read_text())
for s in sources:
 match=next((r for r in fetch_log if r['url']==s['url']),None)
 if match:s['fetchedAt']=match['fetchedAt']
 elif s['id'] in ('pr-qargo-proposed','pr-tower-decree'):
  file=pathlib.Path('research/raw/practice/'+('qargo-proposed' if s['id']=='pr-qargo-proposed' else 'tower-consent')+'.pdf')
  s['fetchedAt']=datetime.datetime.fromtimestamp(file.stat().st_mtime,datetime.timezone.utc).isoformat() if file.exists() else D
 else:s['fetchedAt']=D
merges={'/us-expansion/area-developer-vs-master/':'/us-expansion/master-franchise-vs-area-development/','/us-expansion/national-accounts-and-territories/':'/us-expansion/territory-national-accounts/'}
for g in guides:
 if g['path'] in merges:
  g['status']='draft';g['mergedInto']=merges[g['path']];g['reviewStatus']='Merged into canonical guide after near-duplicate editorial review'
for r in rules:
 r['dependentPaths']=[p for p in r['dependentPaths'] if p not in merges]
for name,data in [('case-guides',cases),('industry-guides',guides),('practice-sources',sources),('practice-rules',rules)]:
 (ROOT/(name+'.json')).write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n')
print(json.dumps({'cases':len(cases),'publishedCases':sum(g['status']=='published' for g in cases),'blockedCases':sum(g['status']=='blocked' for g in cases),'industryAndPracticeGuides':len(guides),'sources':len(sources),'rules':len(rules)},indent=2))
